/**
 * Whether {@link initRouterIntegration} has already run for this JS runtime.
 */
export function isInitialized(): boolean {
  return initialized;
}

/**
 * Enables the router's navigation events and subscribes to screen-focus
 * notifications. Returns a function that removes the subscription.
 */
export function initListeners(): () => void {
  const router = getRouterGlobal();
  router?.navigationEvents?.enable?.();
  router?.navigationEvents?.saveCurrentPathname?.();

  let active = true;
  router?.navigationEvents?.addListener?.('pageFocused', () => {
    if (!active) {
      return;
    }
  });

  return () => {
    active = false;
  };
}

